-- Restriccion FK: descuentproductmateriaprima y movimientosalarioproductor
--                 hacia productormateriaprima
-- =====================================================================================

-- DIAGNOSTICO: Registros huerfanos (ejecutar antes para verificar)
-- descuentproductmateriaprima: 194 huerfanos (idproductormateriaprima 166=110, 354=84)
-- movimientosalarioproductor:  7 huerfanos   (idproductormateriaprima 166=4, 746=1, 739=1, 745=1)

-- Paso 1: Verificar huerfanos antes de limpiar
SELECT 'descuentproductmateriaprima' AS tabla, d.idproductormateriaprima, COUNT(*) AS cantidad
FROM descuentproductmateriaprima d
WHERE d.idproductormateriaprima NOT IN (SELECT idproductormateriaprima FROM productormateriaprima)
GROUP BY d.idproductormateriaprima;

SELECT 'movimientosalarioproductor' AS tabla, m.idproductormateriaprima, COUNT(*) AS cantidad
FROM movimientosalarioproductor m
WHERE m.idproductormateriaprima IS NOT NULL
  AND m.idproductormateriaprima NOT IN (SELECT idproductormateriaprima FROM productormateriaprima)
GROUP BY m.idproductormateriaprima;

